property.value:
//MethodDeclaration[ModifierList/Annotation[@SimpleName = ('Test', 'ParameterizedTest', 'RepeatedTest', 'TestFactory', 'TestTemplate')]]//(IfStatement | ForStatement | ForeachStatement | WhileStatement | DoStatement | SwitchStatement)
  [not(ancestor::*[self::IfStatement or self::ForStatement or self::ForeachStatement or self::WhileStatement or self::DoStatement or self::SwitchStatement])]
  [.//MethodCall[starts-with(@MethodName, 'assert') or @MethodName = ('verify', 'fail', 'assertThat')]]

//MethodCall[@MethodName = ('assertTrue', 'assertFalse')][ArgumentList/*[1][self::InfixExpression[@Operator = ('==', '!=')] or self::MethodCall[@MethodName = 'equals']
    or self::UnaryExpression[@Operator = '!']/MethodCall[@MethodName = 'equals']]]
|
//MethodCall[@MethodName = 'assertThat'][count(ArgumentList/*) = 1][ArgumentList/*[1][self::MethodCall[@MethodName = 'equals'] or self::InfixExpression[@Operator = ('==', '!=')]]]

//MethodCall[@MethodName = 'assertThat'][count(ArgumentList/*) = 1][ArgumentList/*[1][self::BooleanLiteral or self::NumericLiteral or self::StringLiteral or self::NullLiteral]]
|
//MethodCall[@MethodName = ('assertTrue', 'assertFalse')][ArgumentList/BooleanLiteral]
|
//MethodCall[@MethodName = ('assertEquals', 'assertSame')][ArgumentList/*[1][self::BooleanLiteral or self::NumericLiteral or self::StringLiteral or self::VariableAccess][@Image = ../*[2]/@Image]]

//MethodDeclaration[ModifierList/Annotation[@SimpleName = ('Test', 'ParameterizedTest', 'RepeatedTest', 'TestFactory', 'TestTemplate')]]
  [.//MethodCall[@MethodName = ('verify', 'verifyNoInteractions', 'verifyNoMoreInteractions')][ArgumentList/*]]
  [not(.//MethodCall[(starts-with(@MethodName, 'assert') or starts-with(@MethodName, 'expect') or starts-with(@MethodName, 'andExpect') or starts-with(@MethodName, 'verifyComplete') or starts-with(@MethodName, 'verifyError') or starts-with(@MethodName, 'fail') or @MethodName = ('should', 'shouldHaveNoMoreInteractions'))])]
